{
  "table": {
    "name": "comments",
    "purpose": "One row per comment on a Stack Exchange-style Q&A site. Comments are short remarks attached to posts (questions or answers) via PostId, written by users, with a creation timestamp, body text, and an upvote score. The content (mentions of @whuber, @probabilityislogic, Harrell's 'RMS' book, regression/time-series/tree topics) strongly suggests a statistics Q&A site, likely Cross Validated (stats.stackexchange.com)."
  },
  "columns": {
    "CreationDate": {
      "role": "date",
      "name": "comment_creation_timestamp",
      "description": "Date and time the comment was posted. Values span 2009-02-02 to 2014-09-14 and are nearly unique per row (uniqueness 0.999), consistent with per-comment creation times on an active site.",
      "status": "resolved"
    },
    "Id": {
      "role": "identifier",
      "name": "comment_id",
      "description": "Primary key: unique identifier of the comment (174,285 distinct values = row count). The 'referenced_by' joins to postHistory.PostId, postLinks.LinkTypeId, posts.PostTypeId and posts.ParentId are numeric coincidences (post ids and small type codes), not genuine references to comments.",
      "status": "resolved"
    },
    "PostId": {
      "role": "foreign_key",
      "name": "post_id",
      "description": "Foreign key to posts.Id: the question or answer the comment was posted on. Many comments per post (top post has 45; 53,416 distinct posts). The join to postHistory.Id is coincidental; the real target is posts.Id.",
      "status": "resolved"
    },
    "Score": {
      "role": "numeric",
      "name": "upvote_count",
      "description": "Upvote score of the comment. Non-negative (min 0, max 90) and heavily skewed: ~77% of comments have score 0, consistent with Stack Exchange comment scores, which count upvotes only (comments cannot be downvoted).",
      "status": "resolved"
    },
    "Text": {
      "role": "free_text",
      "name": "comment_body",
      "description": "Body text of the comment. Free text, nearly unique per row; typical Q&A comment content such as @username replies, thanks, clarifying questions, and moderation notes ('While this link may answer the question, it is better to include the essential parts...').",
      "status": "resolved"
    },
    "UserDisplayName": {
      "role": "identifier",
      "name": "author_display_name",
      "description": "Display name of the comment author, populated only when the author's user account no longer exists: null in 98.4% of rows, exactly complementing UserId's 1.6% null rate. Values like 'user10525' match Stack Exchange's anonymized deleted-account naming; others are real names (e.g. 'Mariano Suárez-Alvarez').",
      "status": "resolved"
    },
    "UserId": {
      "role": "foreign_key",
      "name": "author_user_id",
      "description": "Foreign key to users.Id: the user who wrote the comment. Null in 1.6% of rows, precisely where UserDisplayName is filled (deleted accounts). 13,647 distinct commenters; the most prolific (Id 919) wrote 13,220 comments.",
      "status": "resolved"
    }
  }
}
